/**
 * Markdown.Blocks: a reply’s blocks, each as the member that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  Each,
  claimSlot,
  inlineText,
  markdownHeadingLevel,
  scope,
  type MarkdownBlock,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import CodeBlock from '../structure/CodeBlock'
import Heading from '../structure/Heading'
import MarkdownInlines from './MarkdownInlines'
import Separator from '../structure/Separator'
import Table from '../structure/Table'
import TableBody from '../structure/TableBody'
import TableCell from '../structure/TableCell'
import TableHead from '../structure/TableHead'
import TableHeader from '../structure/TableHeader'
import TableRow from '../structure/TableRow'
import Text from '../structure/Text'
import type { CitationSource } from './SourceList'

export interface MarkdownBlocksProps {
  blocks: MarkdownBlock[]
  size: 'sm' | 'md'
  sources: CitationSource[]
  /**
   * The shallowest heading depth in the reply, which is level 2.
   */
  shallowest: number
  /**
   * Whether the caret ends the last block.
   */
  caret: boolean
}

/** Markdown.Blocks: a reply’s blocks, each as the member that draws its kind. */
export default function MarkdownBlocks(given: MarkdownBlocksProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <Each of={props.blocks} by={(_block, index) => index} renew>
        {(block, index) => (
          <>
            {block.kind === 'paragraph' ? (
              <Text size={props.size}>
                <MarkdownInlines nodes={block.children} sources={props.sources} />
                {props.caret && index() === props.blocks.length - 1 ? (
                  <span class={styles.caret} aria-hidden="true" />
                ) : null}
              </Text>
            ) : block.kind === 'heading' ? (
              <Heading level={markdownHeadingLevel(block.depth, props.shallowest)}>
                {inlineText(block.children)}
              </Heading>
            ) : block.kind === 'code' ? (
              <CodeBlock copyable={block.closed}>{block.text}</CodeBlock>
            ) : block.kind === 'quote' ? (
              <blockquote class={styles.quote}>
                <MarkdownBlocks
                  blocks={block.children}
                  size={props.size}
                  sources={props.sources}
                  shallowest={props.shallowest}
                  caret={props.caret && index() === props.blocks.length - 1}
                />
              </blockquote>
            ) : block.kind === 'list' ? (
              <Dynamic
                component={block.ordered ? 'ol' : 'ul'}
                class={styles.list}
                start={block.ordered && block.start !== 1 ? block.start : undefined}
              >
                <Each of={block.items} by={(_item, position) => position} renew>
                  {(item, position) => (
                    <li class={styles.item}>
                      <MarkdownBlocks
                        blocks={item}
                        size={props.size}
                        sources={props.sources}
                        shallowest={props.shallowest}
                        caret={
                          props.caret &&
                          index() === props.blocks.length - 1 &&
                          position() === block.items.length - 1
                        }
                      />
                    </li>
                  )}
                </Each>
              </Dynamic>
            ) : block.kind === 'table' ? (
              <Table>
                <TableHead>
                  <TableRow>
                    <Each of={block.header} by={(_head, column) => column} renew>
                      {(head, column) => (
                        <TableHeader numeric={block.align[column()] === 'end'}>
                          <MarkdownInlines nodes={head} sources={props.sources} />
                        </TableHeader>
                      )}
                    </Each>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <Each of={block.rows} by={(_row, line) => line} renew>
                    {(row) => (
                      <TableRow>
                        <Each of={row} by={(_value, column) => column} renew>
                          {(value, column) => (
                            <TableCell numeric={block.align[column()] === 'end'}>
                              <MarkdownInlines nodes={value} sources={props.sources} />
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                    )}
                  </Each>
                </TableBody>
              </Table>
            ) : block.kind === 'rule' ? (
              <Separator />
            ) : null}
          </>
        )}
      </Each>
    )
  })
}
